void testMassConversions() {
    std::cout << "[Test] Mass Conversions..." << std::endl;

    MiscEngine engine;
    engine.setCategory(1); // Mass

    // 1 kg = 2.20462 lb (indices: kg=0, lb=4)
    engine.setAmount(1.0);
    engine.setFromIndex(0); // kg
    engine.setToIndex(4);   // lb
    double result = engine.result();
    if (std::abs(result - 2.20462) > 0.001) {
        std::cerr << "  FAIL: 1 kg to lb = " << result << ", expected ~2.20462" << std::endl;
        return;
    }

    // 1 lb = 0.453592 kg
    engine.setAmount(1.0);
    engine.setFromIndex(4); // lb
    engine.setToIndex(0);   // kg
    result = engine.result();
    if (std::abs(result - 0.453592) > 0.001) {
        std::cerr << "  FAIL: 1 lb to kg = " << result << ", expected ~0.453592" << std::endl;
        return;
    }

    // Same unit identity
    engine.setAmount(5.0);
    engine.setFromIndex(0);
    engine.setToIndex(0);
    result = engine.result();
    if (std::abs(result - 5.0) > 1e-9) {
        std::cerr << "  FAIL: Same unit identity failed: " << result << std::endl;
        return;
    }

    std::cout << "  Passed!" << std::endl;
}

