void testSwap() {
    std::cout << "[Test] Swap Units..." << std::endl;

    MiscEngine engine;
    engine.setCategory(1); // Mass
    engine.setAmount(2.0);
    engine.setFromIndex(0); // kg
    engine.setToIndex(4);   // lb

    double before = engine.result();
    engine.swapUnits();
    double after = engine.result();

    // After swap, amount is still 2.0, from=lb to=kg
    // before = 2 kg in lb, after = 2 lb in kg
    // before * after = 2 * 2 = 4.0 (amount^2)
    if (std::abs(before * after - 4.0) > 0.001) {
        std::cerr << "  FAIL: Swap not reciprocal: before=" << before << " after=" << after << std::endl;
        return;
    }

    std::cout << "  Passed!" << std::endl;
}

