void testColorAndHex() {
    std::cout << "[Test] Color and HEX..." << std::endl;

    MiscEngine engine;
    engine.setCategory(5); // Color

    // Default color
    QColor defaultColor = engine.color();
    if (!defaultColor.isValid()) {
        std::cerr << "  FAIL: Default color should be valid" << std::endl;
        return;
    }

    // Test HEX round-trip
    engine.setHex("#FF0000");
    if (engine.hex() != "#FF0000") {
        std::cerr << "  FAIL: HEX set/get mismatch: " << qPrintable(engine.hex()) << std::endl;
        return;
    }

    // Test RGB components
    if (engine.red() != 255 || engine.green() != 0 || engine.blue() != 0) {
        std::cerr << "  FAIL: RGB components mismatch: " << engine.red() << ", " << engine.green() << ", " << engine.blue() << std::endl;
        return;
    }

    // Test clamping
    engine.setRed(300);
    if (engine.red() != 255) {
        std::cerr << "  FAIL: Red clamping failed: " << engine.red() << std::endl;
        return;
    }

    engine.setGreen(-10);
    if (engine.green() != 0) {
        std::cerr << "  FAIL: Green clamping failed: " << engine.green() << std::endl;
        return;
    }

    engine.setBlue(128);
    if (engine.blue() != 128) {
        std::cerr << "  FAIL: Blue set failed: " << engine.blue() << std::endl;
        return;
    }

    // Test color() reflects RGB
    QColor c = engine.color();
    if (c.red() != 255 || c.green() != 0 || c.blue() != 128) {
        std::cerr << "  FAIL: color() doesn't match RGB: " << c.red() << ", " << c.green() << ", " << c.blue() << std::endl;
        return;
    }

    // Test conversionText for color
    QString conv = engine.conversionText();
    if (!conv.contains("RGB")) {
        std::cerr << "  FAIL: conversionText for color should contain RGB: " << qPrintable(conv) << std::endl;
        return;
    }

    // Test resultText for color
    QString res = engine.resultText();
    if (res != "#FF0080") {
        std::cerr << "  FAIL: resultText for color should be HEX: " << qPrintable(res) << std::endl;
        return;
    }

    std::cout << "  Passed!" << std::endl;
}

